"Abstand Anfang / Ende":"시작 / 끝 간격",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"시작 / 끝 간격을 지정하면 플랜지가 부분 플랜지가 됩니다. 스케치의 다른 닫힌 프로파일은 판의 절단부가 됩니다. 플랜지의 구멍과 창: 모서리를 따른 중심(곡선 모서리에서는 호를 따른 중심), 굽힘 끝부터의 중심, 크기 – 이들은 전개도에도 표시됩니다. 곡선 모서리가 꺾임 없이 인접 모서리로 이어지고 두 모서리의 플랜지가 같은 굽힘 각도를 가지면, 플랜지는 릴리프 없이 서로 이어집니다. “스케치에서 윤곽”은 스케치의 닫힌 프로파일을 플랜지에서 잘라냅니다. X는 모서리를 따라, Y는 플랜지 안쪽으로 향하며, 원점은 모서리 시작점의 굽힘 끝에 있습니다(이동 가능).",
