"Achse: ebene Fläche (Normale), Bohrung (Achse) oder gerade Kante anklicken. Nicht gewählt = Modellrichtung.":"축: 평평한 면(법선), 구멍(축) 또는 직선 모서리를 클릭하세요. 선택하지 않으면 = 모델 방향.",
