"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"모든 환경설정, 도구 모음 사용자 지정, 사용자 단축키를 기본값으로 재설정하시겠습니까?\n\n사용자 공구 라이브러리, 재료, 템플릿은 유지됩니다.",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"사라져야 할 면을 모두 선택하십시오(포켓은 벽면과 바닥, 구멍은 벽면, 모깎기는 둥근 면). 인접한 면은 빈틈을 넘어 연장됩니다. 이 단계는 바디가 변경되면 다시 계산되며, 처음에는 대형 지오메트리 커널을 로드하므로 몇 초가 걸립니다.",
