"Bei Kanten einer gewählten Fläche wird der erste Abstand auf dieser Fläche gemessen.":"선택한 면의 모서리인 경우 첫 번째 거리는 그 면에서 측정합니다.",
"Bei den markierten Operationen noch Flächen im Modell wählen.":"표시된 작업에서는 모델의 면을 아직 선택해야 합니다.",
"Bei „Bohrungen“ liegt das Teil auf der Fläche an dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"“구멍”에서는 부품이 구멍의 끝 중 클릭 지점에 더 가까운 쪽의 면 위에 놓입니다. 여러 구멍을 차례로 클릭한 다음 “완료”를 누르세요.",
"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"“구멍”에서는 부품이 구멍의 끝 중 클릭 지점에 더 가까운 쪽에 면과 나란히 들어갑니다. 여러 구멍을 차례로 클릭한 다음 “완료”를 누르세요.",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"“구멍”에서는 머리가 구멍 중 클릭 지점에 더 가까운 쪽에 놓이고, 축은 구멍 안쪽을 향합니다. 여러 구멍을 차례로 클릭한 다음 “완료”를 누르세요.",
"Beide (in zwei Körper teilen)":"양쪽(두 바디로 분할)",
"Beide Höhen gelten über der Rohteil-Oberkante.":"두 높이 모두 소재 상면 기준입니다.",
"Beide Netze müssen geschlossen sein – zuerst „Reparieren“":"두 메시가 모두 닫혀 있어야 합니다 – 먼저 “복구”를 실행하세요",
"Beide Netze werden ein Netzkörper. Sie werden nicht verschmolzen: sich durchdringende Teile bleiben, wie sie sind.":"두 메시가 하나의 메시 바디가 됩니다. 융합되지 않으며, 서로 관통하는 부분은 그대로 남습니다.",
