"DXF-Datei in diese Skizze einfügen":"이 스케치에 DXF 파일을 삽입합니다",
"DXF-Import fehlgeschlagen:":"DXF 가져오기 실패:",
"DXF: {0} Kreise, {1} Konturen eingefügt{2}":"DXF: 원 {0}개, 윤곽 {1}개를 삽입했습니다{2}",
