"Drehen: Vorsatz letzte Konturzeile":"선삭: 마지막 윤곽 행 접두",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"회전: 각도(°, 반시계 방향), 회전 중심 X, 회전 중심 Y, 복사 수(0 = 회전)",
"Drehen: Y-Achse aus":"선삭: Y축 끄기",
