"Drehgelenk angelegt – mit dem Regler bewegen.":"회전 조인트를 만들었습니다. 슬라이더로 움직일 수 있습니다.",
"Drehgeschwindigkeit":"회전 속도",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Y축이 있는 선반: 단면의 렌치 평면, 윤곽, 포켓을 공작물을 고정한 채(C 고정) X와 Y로 가공합니다. 극좌표 보간보다 정확합니다. Y축 이동 범위를 넘는 부분은 극좌표 보간으로 남습니다.",
