"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"버링 {0}: 밑구멍 Ø {1} mm가 Ø {2} mm로 확대됩니다 (계수 {3}).",
