"Ebene Flächen des Körpers werden entlang ihrer Normalen extrudiert. Automatisch: nach außen = Material hinzufügen, nach innen (negativ) = ausschneiden.":"바디의 평면이 법선 방향으로 돌출됩니다. 자동: 바깥쪽 = 재료 추가, 안쪽(음수) = 잘라내기.",
