"Ecke, Kantenende, Konstruktionspunkt oder Fläche anklicken.":"꼭짓점, 모서리 끝점, 구성 점 또는 면을 클릭하세요.",
"Ecken":"꼭짓점 수",
"Ecken und Kantenenden rasten beim Anklicken ein. Punkte dienen als Bezug für Ebene durch drei Punkte und Achse durch zwei Punkte.":"꼭짓점과 모서리 끝점은 클릭할 때 스냅됩니다. 점은 세 점을 지나는 평면과 두 점을 지나는 축의 기준으로 사용됩니다.",
