"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"사용자 지정 단축키: 도구 모음에서 그룹 메뉴(▾)를 열고, 명령 옆의 ⋮를 클릭 → “키보드 단축키 변경 …”.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"추가한 치수와 주석은 시트에서 마우스로 끌어 조정할 수 있습니다(치수선 간격, 지시선 각도, 각도 호의 반지름). 모퉁이 두 곳을 클릭하면 길이 치수가 됩니다. 평면도에서 원의 가장자리를 클릭하면 지름(또는 반지름)이 됩니다. 각도는 먼저 꼭짓점을 클릭한 다음 양쪽 변 위의 점을 하나씩 클릭합니다. 모따기는 비스듬한 모서리의 양 끝을 클릭하면 예를 들어 2×45°가 됩니다. 각 치수 뒤의 텍스트 칸에는 ±0,1, H7, 4× 같은 추가 표기를 입력할 수 있습니다.",
"Eigene Symbolfarbe":"사용자 아이콘 색",
"Eigene Werte":"사용자 값",
