"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"둥근 엔드밀은 모든 내측 모서리에 자신의 반경만큼 남기므로, 각진 상대 부품이 들어가지 않습니다. 릴리프는 날카로운 내측 모서리마다 모서리 안으로 짧게 들어갔다가 돌아옵니다.{0}{1}",
