"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"로프트에는 서로 다른 평면에 닫힌 프로파일이 있는 스케치 두 개가 필요합니다.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"로프트에는 곡선이 하나씩 있는 스케치 두 개가 필요합니다(서로 다른 평면).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"로프트할 수 없습니다 – 단면을 확인하세요(각각 닫힌 프로파일 하나, 비틀리지 않음)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"로프트할 수 없습니다 – 스케치당 곡선 하나, 같은 방향, 비틀리지 않음",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"기본 단축키 „{0}“을(를) 대체합니다.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"먼저 이동할 바디의 면을 클릭한 다음, 다른 바디의 대상 면을 클릭하십시오. 첫 번째 클릭 지점이 두 번째 지점에 겹치고 면이 서로 맞닿을 때까지 바디가 회전 및 이동됩니다.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"먼저 이동할 바디의 모서리를 클릭한 다음, 다른 바디의 대상 모서리를 클릭하십시오. 직선 모서리는 서로 일치합니다(중점끼리). 원형 모서리(구멍과 핀)는 축이 같은 방향으로 정렬되고 중심점이 합쳐집니다.",
"Erst ein Setup anlegen.":"먼저 셋업을 만드세요.",
"Erst ein Setup mit Operationen anlegen.":"먼저 작업이 포함된 셋업을 만드세요.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"먼저 스케치 또는 구성 평면을 선택하세요. 그러면 Ctrl+8이 그 면을 수직으로 바라봅니다.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"먼저 설계에서 바디를 만들거나 메시(STL)를 삽입하세요.",
"Erst einen Körper in KONSTRUKTION erstellen.":"먼저 설계에서 바디를 만드세요.",
"Erst einen Namen für das Profil eingeben.":"먼저 프로필 이름을 입력하십시오.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"먼저 템플릿을 클릭한 다음 자리 표시자를 선택하세요",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"첫 번째 모서리를 클릭한 다음 반대쪽 모서리를 클릭하세요.",
"Erstellen":"만들기",
