"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"바디의 면을 클릭하면 그 경계가 윤곽으로 스케치에 추가됩니다. 모서리를 클릭하면 해당 모서리만 투영됩니다 (원은 원으로 유지). 투영된 형상은 보라색입니다.",
"Fläche ersetzen":"면 대체",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"면 대체: 평면을 다른 평면으로 옮깁니다 – 바디가 커지거나 줄어듭니다",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"창 뒤쪽의 영역 – 위에서 “사용자” 테마를 선택한 경우에 적용됩니다",
"Fläche löschen":"면 삭제",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"면 삭제: 구멍, 포켓, 모깎기 또는 모따기를 제거합니다 – 인접한 면이 빈틈을 메웁니다",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"마우스 포인터 아래의 면이나 모서리를 색으로 표시합니다",
"Fläche versetzen":"면 오프셋",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"면 오프셋: 평면을 이동하고 구멍과 핀의 지름을 변경합니다",
"Fläche wählen":"면 선택",
