"Flächen (alle Kanten ringsum)":"면 (둘레의 모든 모서리)",
"Flächen (aufeinander legen)":"면 (서로 맞대기)",
"Flächen am Körper":"바디의 면",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"부품 끝단의 평면(2면, 사각, 육각)을 Z 방향 구동 엔드밀로 가공합니다. 렌치 평면 폭 = 평면과 회전축 사이 거리의 2배. X와 C가 함께 움직입니다 (극좌표 보간, Fanuc G12.1). 포스트 프로세서에 이 템플릿이 없으면 짧은 X/C 단계로 출력됩니다.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"두께를 줄 면을 클릭하세요(다시 클릭하면 해제).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"구배를 줄 면을 클릭합니다(다시 클릭하면 해제).",
"Flächen anklicken, die offen sein sollen.":"열어 둘 면을 클릭합니다.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"오프셋할 면을 클릭하세요(다시 클릭하면 해제).",
"Flächen im Modell":"모델의 면",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"공통 모서리를 가진 서피스는 하나로 결합됩니다. 셸이 전체적으로 닫혀 있으면 솔리드 바디가 만들어집니다(이후 일반적으로 편집 가능). 공차보다 큰 틈은 열린 상태로 남습니다.",
