"Frei: das Werkstück dreht sich in alle Richtungen (auch über Kopf). Eingeschränkt: die Z-Achse bleibt senkrecht.":"자유: 공작물이 모든 방향(거꾸로 포함)으로 회전합니다. 제한: Z축이 수직으로 유지됩니다.",
