"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 파일(.f3d)은 Autodesk의 비공개 형식이므로 읽을 수 없습니다.\n\nFusion 360에서 파일 → 내보내기 → STEP (.stp)를 선택한 다음, 그 파일을 여기에서 가져오십시오.",
"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Fusion 360 포스트 프로세서 “{0}”을(를) 가져왔습니다:\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"위에서 접근할 수 있는 모든 날카로운 외측 모서리를 따라가며 디버링 깊이만큼 깎아냅니다. 모따기 커터로는 모따기로(공구 축 수직, 팁은 모서리 바깥), 볼/롤리팝 엔드밀로는 둥글게 가공합니다.",
"Führungszapfen-Ø":"가이드 핀 Ø",
