"Für Antasten einen 3D-Taster als Werkzeug wählen":"프로빙에는 공구로 3D 프로브를 선택하십시오",
"Für Gewindebohren einen Gewindebohrer wählen":"탭핑에는 탭을 선택하십시오",
"Für Gewindefräsen einen Gewindefräser wählen":"나사 밀링에는 나사 밀링 커터를 선택하십시오",
"Für Setups, die nicht von oben bearbeitet werden":"위에서 가공하지 않는 셋업용",
"Für Sweep wird ein Pfad gebraucht: offene Linie in einer Skizze (mit Enter beenden).":"스윕에는 경로가 필요합니다. 스케치에 열린 선을 그리세요(Enter로 종료).",
"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"터치패드용: 스크롤하면 화면이 이동하고, 두 손가락을 벌리면(또는 Ctrl + 마우스 휠) 확대/축소됩니다",
"Für V-Gravur einen Fasenfräser (V) wählen":"V 조각에는 모따기 커터(V)를 선택하십시오",
"Für diese Strategie nicht geeignet":"이 전략에는 적합하지 않음",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"경사 방향에는 구성 축(두 점, 원통 또는 두 평면 기준)을 만드세요. 그러면 여기에 방향으로 표시됩니다.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"선을 따라 트로코이달 밀링을 하려면 슬롯 폭을 지정하십시오",
