"Gerade (radial)":"직선(반경 방향)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"어떤 프로파일에도 속하지 않는 스케치의 직선입니다 (보조선 포함). 굽힘: 선은 굽힘 영역의 중심이며 그곳의 스케치가 블랭크가 됩니다. 판의 가장 큰 부분은 그대로 있고, 선 너머의 모든 부분은 플랜지와 함께 회전합니다. 선은 판 전체에 적용됩니다. 비드: 선을 따라 생기는 리브로, 단면과 양 끝이 둥글며 판금은 두께를 유지합니다.",
"Geraden, Bögen und Kreise":"직선, 호, 원",
"Gerader Teil (nach der Biegung)":"직선 부분 (굽힘 후)",
"Geradheit":"진직도",
"Geradlinig":"직선형",
"Gerät":"장치",
"Gerät per USB oder Funkempfänger anschließen":"장치를 USB 또는 무선 수신기로 연결하세요",
"Gesamtabstand":"전체 거리",
"Gesamte Bearbeitungszeit":"총 가공 시간",
"Gesamte Rechenzeit":"총 계산 시간",
"Gesamtes axiales Rohteilaufmaß":"전체 축 방향 여유량",
"Gesamtes radiales Rohteilaufmaß":"전체 반경 방향 여유량",
"Gesamtlänge":"전체 길이",
"Gesamtwinkel":"총 각도",
