"Geschlossen (Gehrung)":"닫힘 (마이터)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"닫힘: 인접한 두 모서리의 플랜지는 모서리의 이등분선까지 이어지며 그곳에 틈을 남깁니다. 코너 릴리프는 굽힘 영역이 교차하는 위치에 놓이며, 전개도와 굽힌 부품 모두에 적용됩니다. 곡선 모서리의 플랜지도 실제 모서리에서는 미터(맞각) 절단됩니다 (그곳에는 코너 릴리프가 없습니다).",
"Geschlossene Kette {0}":"닫힌 체인 {0}",
"Geschlossene Profile begrenzen den Bereich.":"닫힌 프로파일이 영역을 제한합니다.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"활성 스케치의 닫힌 프로파일을 색으로 채웁니다",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"닫힌 프로파일이 평면 서피스가 됩니다. 예: 뚜껑과 바닥. 이후 서피스를 봉합하여 바디로 만들 수 있습니다.",
"Geschnitten ab X":"단면 시작 X",
