"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"가져온 바디에는 설계 이력이 없지만 계속 편집(모깎기, 모따기, 잘라내기 등)하거나 CAM에 사용할 수 있습니다. “Y축이 위”를 선택하면 Y축이 위쪽인 프로그램의 모델이 올바른 방향으로 놓입니다.",
