"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"각 스케치의 첫 번째 곡선(열림 또는 닫힘). 곡선은 스킨(두께 없는 서피스)으로 연결됩니다.",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"판재 한 장당 파일 하나가 만들어집니다. 경로는 외곽선 옆의 폐기 영역에서 커프 폭의 절반(밀링에서는 커터의 절반)만큼 떨어져 지나갑니다. 컷아웃은 해당 부품의 외곽선보다 먼저 가공되며, 각 윤곽은 폐기 영역에서 시작하는 리드인으로 시작합니다. 켜기는 M3(레이저: M3 S…), 끄기는 M5, 피어싱 시간은 G4로 출력됩니다. 공작물 원점은 판재의 왼쪽 아래 모서리이며, 밀링에서 Z0은 판의 윗면입니다. 사용 전에 기계 또는 NC 시뮬레이터에서 프로그램을 확인하세요.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"축마다 개별로: 모서리, 꼭짓점, 면 또는 구멍을 클릭하세요. 설정하지 않은 축은 소재 점에서 가져옵니다.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"각 작업을 프로그램 끝의 서브프로그램(LBL)으로 만들고 CALL LBL로 호출합니다",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"스케치의 모든 원이 구멍의 중심이 됩니다. 구멍은 스케치 법선의 반대 방향(재료 안쪽)으로 뚫립니다.",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"스케치의 모든 원이 중심(스케치 좌표)을 기준으로 회전하며 반복됩니다. 피치원 반지름만큼 떨어진 원은 볼트 서클이 됩니다.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"스케치의 모든 원이 격자가 됩니다. 스케치의 X, Y 방향 간격을 입력합니다(음수도 가능).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"이제 두 번째 변 위의 점을 선택하세요.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"이제 각 방향을 한 번씩 끝까지 움직이세요: 밀기, 당기기, 누르기, 기울이기, 비틀기(10초) …",
"Jetzt laden":"지금 다운로드",
