"K-Faktor {0} liegt außerhalb des üblichen Bereichs 0,25 … 0,5 – der Zuschnitt weicht dann meist vom gebogenen Teil ab.":"K-계수 {0}이(가) 일반 범위 0,25 … 0,5를 벗어났습니다. 이 경우 절단 형상이 굽힌 부품과 달라지는 경우가 많습니다.",
