"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"보정: 두 점 사이의 실제 거리 (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"보정: 거리를 알고 있는 두 점을 이미지에서 클릭하고 실제 거리를 입력하십시오. 이미지가 올바른 축척을 갖게 됩니다.",
"Kalibrieren: zweiten Punkt im Bild anklicken (Esc bricht ab).":"보정: 이미지에서 두 번째 점을 클릭하십시오 (Esc로 취소).",
