"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"모서리 {0}: 180°를 넘는 굽힘 각도는 제작할 수 없습니다.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"모서리 {0}: 곡선 모서리의 플랜지 – 성형 시 가장자리가 {1} % 압축됩니다 (주름 위험). 이 부분의 블랭크는 근사값입니다.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"모서리 {0}: 곡선 모서리의 플랜지 – 성형 시 가장자리가 {1} % 늘어납니다 (균열 위험). 이 부분의 블랭크는 근사값입니다.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"모서리 {0}: 플랜지 치수 {1} mm가 굽힘({2} mm)보다 작습니다",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"모서리 {0}: 호가 이 플랜지에 비해 너무 작습니다",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"모서리 {0}: 간격 때문에 남는 플랜지가 없습니다.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"모서리 {0}: 플랜지가 굽힘선과 교차합니다 – “시작 / 끝 간격”으로 굽힘 앞에서 끝나게 하세요",
"Kante {0}: die Lasche liegt in einer Biegezone":"모서리 {0}: 플랜지가 굽힘 영역에 있습니다",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"모서리 {0}: 존재하지 않는 플랜지에 속한 절단부가 있습니다.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"모서리 {0}: 플랜지의 절단부가 굽힘에서 {1} mm 옆에 있습니다 (판 두께의 2배 미만) – 굽힐 때 변형됩니다.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"모서리 {0}: 컷아웃이 굽힘에서 {1} mm 거리에 있습니다 (판 두께의 2배 미만). 굽힘 시 변형됩니다.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"모서리 {0}: 절단부가 플랜지 밖으로 튀어나옵니다.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"모서리 {0}{1}: 플랜지 {2} mm가 판 두께의 2배보다 짧아 프레스 브레이크로 굽히기 어렵습니다.",
"Kanten":"모서리",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"모서리 (직선은 일치, 원은 동심)",
"Kanten anklicken (erneut klicken entfernt).":"모서리를 클릭하세요(다시 클릭하면 해제).",
