"Kanten wählen, die einen geschlossenen Rand bilden":"닫힌 경계를 이루는 모서리 선택",
"Kantenglättung":"안티앨리어싱",
"Kantenhöhe":"모서리 높이",
"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"캡에서 손을 떼고 “영점 보정”을 선택하세요. 그런 다음 각 방향을 시험해 보세요. 막대가 움직이고, 정지 상태에서는 회색 불감대 안에 있어야 합니다.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"캡을 밀기 = 이동, 누르기/당기기 = 확대·축소, 기울이기와 비틀기 = 모델 회전. 스케치에서는 이동과 확대·축소만 가능합니다. SpaceMouse Pro/Enterprise: T, F, R = 위, 앞, 오른쪽 뷰. 아무 반응이 없으면 3Dconnexion 드라이버를 잠시 종료한 후 다시 연결하세요.",
