"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"{0}개 점의 윤곽 – Okuma: G85 (LAP)와 윤곽 G81…G80, Fanuc: G71 P…Q…. 제어기는 자체 절입 분할로 황삭하며, 여기의 시뮬레이션은 WerkFab 경로입니다.",
