"Konturen außen und innen":"외곽 및 내부 윤곽",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"윤곽은 어두운 영역의 가장자리를 따릅니다. 중심선은 선의 가운데를 따라가므로 조각과 선화에 적합합니다. “직선, 호, 원”은 직선 모서리, 날카로운 모퉁이, 둥근 부분, 원을 인식하며, “폴리라인”은 이미지를 점 단위로 따라갑니다. 축척은 이후 필요에 따라 “템플릿 보정” 또는 “축척”으로 조정하십시오.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"컨트롤러에서 공구 반경 보정(RL/RR)을 하는 윤곽은 APPR/DEP로 진입·이탈합니다. 보조점과 보정은 컨트롤러가 직접 계산합니다",
