"Kurven":"곡선",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"단면(회전축에 수직) 위 스케치의 곡선을 Z 방향 구동 공구로 가공합니다 (X와 C가 함께 움직입니다. Fanuc: 극좌표 보간 G12.1). 열린 곡선은 왕복으로 가공됩니다. 깊이는 단면부터.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"회전축을 따라 놓인 스케치의 곡선을 원주에 감아, 축을 향한 구동 공구로 가공합니다 (Z와 C가 함께 움직입니다. Fanuc: 원통 보간 G7.1). 스케치 평면이 윤곽이 위치하는 각도를 정하며, 스케치의 수평 선분은 부품 둘레의 호가 됩니다. 깊이는 외경부터.",
"Kurzbefehl":"단축키",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"짧은 이동(유지 거리까지)에서는 공구가 후퇴 높이로 올라가지 않고 아래에서 전환 이송 속도로 움직입니다. 충돌 검사가 없으므로 작게 유지하세요.",
"KÖRPER":"바디",
