"Körper als Komponente positionieren":"바디를 구성요소로 배치",
"Körper anklicken, die bearbeitet werden (erneut klicken entfernt).":"가공할 바디를 클릭하세요(다시 클릭하면 해제).",
"Körper anklicken: die Kurven, in denen die Skizzenebene ihn schneidet, kommen in die Skizze.":"바디를 클릭하면 스케치 평면이 바디와 교차하는 곡선이 스케치에 추가됩니다.",
"Körper anklicken: sein Umriss (Schattenriss) auf der Skizzenebene kommt in die Skizze.":"바디를 클릭하면 스케치 평면 위의 외곽선(실루엣)이 스케치에 추가됩니다.",
