"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"셋업의 „소재 → 소재 재료“에서 재료를 선택하세요. 밀도로 소재 중량이 계산되고, Vc는 초경 공구의 기준값이며, 색상은 시뮬레이션에 표시됩니다.",
