"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"서로 이어진 여러 모서리는 하나의 경로로 취급됩니다. 반지름은 체인의 시작부터 끝까지 변하며, 제어점은 체인 전체 길이에 대한 %로 지정합니다. 이는 대형 지오메트리 커널이 계산합니다.",
