"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"제어점을 사용하면 반지름이 지정한 값을 지나며 변합니다(위치는 모서리 길이에 대한 %). 이는 대형 지오메트리 커널이 계산하며, 처음에는 로드하는 데 몇 초가 걸립니다.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D 프로브로는 절삭할 수 없습니다",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"완성품과 비교: 녹색 = 치수대로, 파랑 = 잔여 재료, 빨강 = 과절삭",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"마우스를 윤곽 옆으로 이동(쪽에 따라 방향이 정해짐) · Esc로 종료",
"Mit diesem Werkzeug kann nicht gefräst werden":"이 공구로는 밀링할 수 없습니다",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"탭에는 '탭핑' 사이클만 사용하십시오. 드릴링 사이클은 탭을 부러뜨립니다",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"절입을 여러 번 하면 나사 깊이를 제거량이 거의 같은 단계로 나누어 가공하므로, 작은 나사 밀링 커터와 단단한 재료에 부담이 적습니다. 스프링 패스는 마지막 경로를 절입 없이 한 번 더 따라갑니다.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"NC 프로그램에서 „드릴링 사이클“을 선택하면 제어기 사이클로 출력되고 (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), 선택하지 않으면 개별 동작으로 풀어서 출력됩니다.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"“원본 유지”를 선택하면 원본과 대칭 이미지가 하나의 메시가 되고 대칭 평면 위의 점이 연결됩니다. 열린 절반이 이렇게 닫힌 부품이 됩니다.",
