"Nicht verbundene Teile des Netzes werden zu eigenen Netzkörpern.":"메시에서 연결되지 않은 부분은 각각 별도의 메시 바디가 됩니다.",
"Nicht verwendete Werkzeuge entfernen":"사용하지 않는 공구 제거",
"Nicht übernommen (Halter, Taster oder unbekannter Typ): {0}{1}":"가져오지 않음(홀더, 프로브 또는 알 수 없는 유형): {0}{1}",
"Nichts getroffen – Kante, Ecke, Fläche oder Bohrung anklicken.":"선택된 항목이 없습니다. 모서리, 꼭짓점, 면 또는 구멍을 클릭하세요.",
"Nichts getroffen – auf das Modell klicken.":"선택된 항목이 없습니다. 모델을 클릭하세요.",
"Nichts gewählt – „Auswählen“ und im Modell anklicken.":"선택된 항목이 없습니다. “선택”을 누르고 모델을 클릭하세요.",
"Nichts gewählt – „Auswählen“, dann Flächen oder Kanten im Modell anklicken.":"선택된 항목이 없습니다. “선택”을 누른 다음 모델에서 면 또는 모서리를 클릭하세요.",
"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"변경 사항 없음: 인접한 면이 이 틈을 닫지 못합니다. 서로 연결된 면을 함께 선택하십시오(예: 포켓의 벽과 바닥)",
"Nichts zu schruppen":"황삭할 부분이 없습니다",
"Nichts zum Umbenennen gewählt.":"이름을 바꿀 항목이 선택되지 않았습니다.",
"Niedrig (0,05 mm)":"낮음(0,05 mm)",
"Noch kein Dreh-Setup: „Neues Setup“ → Bearbeitung „Drehen“ wählen.":"선삭 셋업이 아직 없습니다. “새 셋업” → 가공 “선삭”을 선택하세요.",
"Noch kein Fräs-Setup vorhanden.":"밀링 셋업이 아직 없습니다.",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"아직 바디가 선택되지 않았습니다. 그때까지는 상대 직육면체 크기가 적용됩니다.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"아직 바디가 없습니다. 먼저 설계에서 모델링하십시오.",
"Noch keine Designs gespeichert.":"저장된 디자인이 아직 없습니다.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"아직 댓글이 없습니다. +로 디자인에 메모를 남기세요.",
"Noch keine Operation":"작업이 아직 없습니다",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"템플릿이 아직 없습니다. 템플릿은 전략을 모든 설정(공구, 절삭 데이터, 높이, 패스 수, 연결)과 함께 저장하여 다른 셋업과 설계에서 다시 사용할 수 있게 합니다.",
"Noch keine Werkzeuge im Dokument.":"문서에 아직 공구가 없습니다.",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"아직 없습니다. 형상을 선택한 다음 위의 구속조건에서 도구를 클릭하세요.",
"Noch nicht gespeichert (Strg+S)":"아직 저장되지 않음(Ctrl+S)",
"Normal":"일반",
"Normal ↔ Konstruktion (X)":"일반 ↔ 구성 (X)",
