"Normteil einfügen":"규격 부품 삽입",
"Normteil unbekannt":"알 수 없는 규격 부품",
"Normteil: Bohrung (Zylinderfläche) im Modell anklicken.":"규격 부품: 모델의 구멍(원통면)을 클릭하세요.",
"Normteil: {0} eingefügt – weitere Bohrung anklicken oder beenden.":"규격 부품: {0} 삽입됨 – 다른 구멍을 클릭하거나 종료하세요.",
