"Nullen am Ende kürzen":"끝자리 0 생략",
"Nullpunkt":"공작물 원점",
"Nullpunkt der Skizze ab Ende der Biegung (in die Lasche hinein) mm":"스케치 원점, 굽힘 끝부터 (플랜지 안쪽으로) mm",
"Nullpunkt der Skizze entlang der Kante (vom Kantenanfang) mm":"스케치 원점, 모서리를 따라 (모서리 시작점부터) mm",
"Nullpunkt gespeichert (Rauschen ±{0} → Totzone {1}). Jetzt optional „Maximalausschlag messen“.":"영점을 저장했습니다(노이즈 ±{0} → 불감대 {1}). 필요하면 이제 “최대 편차 측정”을 실행하세요.",
"Nullpunkt kalibrieren":"영점 보정",
"Nullpunkt, Totzone, Empfindlichkeit und Richtung der 3D-Maus":"3D 마우스의 영점, 불감대, 감도 및 방향",
"Nullpunkt, Totzone, Empfindlichkeit und Richtung jeder Achse einstellen":"각 축의 영점, 불감대, 감도, 방향 설정",
"Nullpunkt-Tabelle":"공작물 원점 테이블",
"Nummer":"번호",
"Nummer schon belegt, umnummeriert: {0}{1}":"번호가 이미 사용 중이어서 다시 매겼습니다: {0}{1}",
"Nur ASCII-Zeichen":"ASCII 문자만",
"Nur Außenkonturen":"외곽 윤곽만",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"컨트롤러 사이클은 외곽 윤곽(보스)만 지원합니다",
"Nur Durchmesser (Form wie dieses Werkzeug)":"직경만 (형상은 이 공구와 동일)",
"Nur Innenkonturen (Öffnungen)":"내부 윤곽만 (개구부)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"컨트롤러 사이클은 사각형 및 원형 포켓만 지원합니다",
"Nur Skizze":"스케치만",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"더 큰 커터가 모서리에 남긴 부분만 가공합니다.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"더 큰 커터가 닿지 못한 윤곽 부분(안쪽 모서리, 좁은 곳)만 따라갑니다. 진입/진출 호, 탭, 정삭 패스는 없으며 보정은 컴퓨터에서 처리합니다.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"기준 공구가 닿지 못한 곳만 가공합니다. 평탄한 영역은 평행, 가파른 영역은 등고선 방식입니다. 목록의 공구를 선택하면 그 형상도 반영되며, 예를 들어 코너 R 엔드밀이 필릿에 남기는 부분이 해당됩니다.",
"Nur ebene Flächen können als Skizzenebene dienen.":"평평한 면만 스케치 평면으로 사용할 수 있습니다.",
"Nur ebene Flächen können extrudiert werden":"평면만 돌출할 수 있습니다",
"Nur ebene Flächen lassen sich ersetzen":"평면만 교체할 수 있습니다",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"평면과 원통면(구멍, 보스)만 오프셋할 수 있습니다",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"공구 쪽 위를 향한 평평한 면만 가능합니다(이 셋업에서는 수평).",
"Nur für Außen-Drehmeißel":"외경 선삭 공구 전용",
"Nur in Operationen verwendete":"작업에서 사용 중인 것만",
"Nur in diesem Projekt":"이 프로젝트에만",
"Nur mit Korrektur „Im Rechner“.":"보정이 „컴퓨터 내“일 때만 가능합니다.",
"Nur stärkste Achse":"가장 큰 축만",
"Nut":"홈",
"Nut angetrieben":"라이브 홈 가공",
"Nut angetrieben (C-Achse)":"구동 공구 홈 가공(C축)",
"Nut liegt nicht am Teil":"홈이 부품 위에 없습니다",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"회전축을 따른 홈(예: 키홈)을 축을 향한 구동 공구로 가공하며, 주축이 부품을 C축으로 고정합니다. 홈 폭 = 엔드밀 Ø. 시작/끝 Z는 모델 Z 기준이며, 홈이 단면까지 이어지면 엔드밀이 앞에서 진입하고 그렇지 않으면 시작 위치에서 플런지합니다. 깊이는 외경부터.",
"Nutbreite bei Linien":"선의 홈 폭",
"Nuten":"홈",
"Nutenfräser":"슬롯 커터",
"Nuttiefe":"홈 깊이",
"Nuttiefe angeben":"홈 깊이를 지정하십시오",
"Nuttiefe {0} mm ist größer als der Radius {1} mm":"홈 깊이 {0} mm가 반경 {1} mm보다 큽니다",
"Nächstes Werkzeug schon vorbereiten (TOOL DEF bzw. T-Wort)":"다음 공구를 미리 준비합니다(TOOL DEF 또는 T 워드)",
"O-Ring (ISO 3601)":"O링 (ISO 3601)",
"OBEN":"상단",
