"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"열린 곡선 또는 닫힌 곡선이 스케치에 수직으로 돌출됩니다. 결과는 서피스(두께 없는 벽)입니다. “두께 주기” 또는 “봉합”으로 솔리드로 만들 수 있습니다.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"열린 곡선 또는 닫힌 곡선이 축을 중심으로 회전됩니다. 결과는 서피스이며 솔리드가 아닙니다.",
