"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"“모델링”을 선택하지 않으면 나사는 표시만 됩니다(빠름). 모델링하면 나사 형상이 실제로 절단됩니다(예: 3D 프린팅용). M8 밑구멍 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP 선삭",
"Okuma OSP-M Fräsen":"Okuma OSP-M 밀링",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53은 기계 좌표로 이동하지 않습니다(G53은 공구 길이 보정을 해제함) – 안전 높이로 후퇴하며 XY 기준 복귀는 출력되지 않았습니다",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: 스무딩 기능이 출력되지 않았습니다(G5.1은 Fanuc 용) – Hi-Cut/Super-NURBS는 기계에서 설정하세요",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: 보정+공구+인선(예: 010101)",
