"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: 모든 기능. Rust 커널(truck, 실험적): 기본 형상, 돌출, 회전, 구멍, 패턴, 대칭, 이동, 축척, 결합, STEP 내보내기. 그 밖의 피처는 “아직 지원되지 않음”으로 표시됩니다.",
