"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"투영 (J): 바디의 면 또는 모서리를 클릭하면 그 투영이 스케치에 추가됩니다",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"모서리와 면 투영에는 기본 커널의 솔리드 바디가 필요합니다. 바디 외곽선과 교차 곡선은 메시에서도 가능합니다.",
"Projizieren: Fläche oder Kante eines Körpers anklicken.":"투영: 바디의 면 또는 모서리를 클릭합니다.",
"Projizierte Fläche: folgt dem Körper, wenn er sich ändert.":"투영된 면: 바디가 변경되면 따라 변경됩니다.",
"Projizierte Kante: folgt dem Körper, wenn er sich ändert.":"투영된 모서리: 바디가 변경되면 따라 변경됩니다.",
"Projizierter Körperumriss: folgt dem Körper, wenn er sich ändert.":"투영된 바디 외곽선: 바디가 변경되면 따라 변경됩니다.",
