"Prägung":"엠보싱",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"엠보싱 {0}: 윤곽이 판 두께의 2배보다 좁습니다 – 빈 공간이 남지 않습니다.",
"Prägung {0}: lässt sich so nicht formen":"엠보싱 {0}: 이 형태로는 성형할 수 없습니다",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"엠보싱 {0}: {1} mm는 판 두께의 3배보다 높습니다 – 벽이 수직이면 판이 찢어집니다.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"엠보싱: 윤곽을 잘라내지 않고 지정한 높이만큼 판에서 밀어냅니다. 접시 딤플: 둥근 구멍의 가장자리를 90° 원뿔 모양으로 눌러 만듭니다 – 얇은 판금의 접시머리 나사용입니다 (− 아래: 나사를 위에서 체결).",
