"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"밑구멍에서 바깥쪽으로 구멍을 황삭하고(정삭 여유량 0,2 mm), 이후 바닥까지 정삭합니다. 보링 바는 밑구멍에 들어가야 합니다.",
"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"동시 4축으로 바깥에서 안쪽으로 황삭합니다. 절입마다 A축 둘레의 나선(+X와 −X 교대)으로 가공하며, 부품에 여유량을 더한 깊이보다 깊어지지 않습니다. 엔드밀 또는 볼 엔드밀을 사용합니다.",
