"Tasche Planfläche (C-Achse)":"단면 포켓(C축)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"선삭 축 방향으로 놓인 스케치의 닫힌 윤곽으로 원주면에 포켓을 만듭니다(내부 윤곽은 아일랜드로 남음). 스케치는 지름에 감기고, 축을 향한 구동식 엔드밀이 안쪽에서 바깥쪽으로 가공합니다(Z와 C가 함께 이동, Fanuc: 원통 보간 G7.1). 커터는 가장 안쪽 링을 따라 램프로 진입합니다.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"스케치의 닫힌 윤곽으로 단면에 포켓을 가공합니다(내부 윤곽은 아일랜드로 남음). Z 방향으로 구동 엔드밀을 사용합니다. 안쪽에서 바깥쪽으로 제거하며, 엔드밀은 가장 안쪽 경로를 따라 램프로 진입하고 한 레벨 안에서는 아래에 머뭅니다. X와 C가 함께 움직입니다 (Fanuc: 극좌표 보간 G12.1). 깊이는 단면부터.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"아일랜드가 있는 포켓입니다. 컨트롤러 사이클은 아일랜드를 처리할 수 없습니다",
