"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"더 긴 모서리를 가운데에서 분할합니다(패스당 한 번). 형상은 그대로입니다. 0이면 모든 모서리를 분할하여 각 삼각형이 네 개가 됩니다. 거친 메시를 부드럽게 하기 전에 유용합니다.",
