"Tippen zeigt die Wirkung sofort rechts in der Vorschau. Klick auf eine NC-Zeile springt zur Vorlage, die sie geschrieben hat; Platzhalter unten per Klick einfügen.":"입력하면 그 결과가 오른쪽 미리보기에 바로 표시됩니다. NC 행을 클릭하면 해당 행을 출력한 템플릿으로 이동하며, 자리 표시자는 아래에서 클릭하여 삽입합니다.",
