"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"스케치 곡선을 원통에 감습니다. X는 그대로 유지되고, 축에 수직인 거리는 전개 Ø 위의 호가 됩니다 (A 회전). 스케치는 A축에 평행해야 하며, 예를 들어 접평면 위에 있어야 합니다. 부품 표면 아래 일정한 깊이로 가공하며, 부품 둘레의 각인, 문자, 홈에 적합합니다.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"3D 윤곽과 같지만 공구가 단차 없이 연속으로 내려가므로 가파른 벽에 진입 자국이 남지 않습니다.",
