"{0}: Ecke anklicken – Linienzug, Rechteck oder Treffpunkt zweier Linien. Das Werkzeug bleibt aktiv, Esc beendet.":"{0}: 모퉁이를 클릭합니다(폴리라인, 직사각형 또는 두 선의 교점). 도구는 계속 활성 상태이며 Esc로 종료합니다.",
"{0}: Fläche oder Kante im Modell anklicken.":"{0}: 모델에서 면 또는 모서리를 클릭하세요.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: GRBL은 공구 반경 보정(G41/G42)을 지원하지 않습니다. 보정 없이 경로를 출력했습니다",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: 공작물 원점 Y/Z가 회전축 A 위에 있지 않습니다(축 위치 Y{1} Z{2}). 4축 동시 가공에서는 공작물 원점을 축 위에 두십시오(소재 점 중심 Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: 포스트 프로세서에 선삭 사이클이 없습니다 – 경로로 출력됨",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: 포스트 프로세서에 극좌표 보간이 없습니다. 면을 짧은 X/C 스텝(C는 도 단위)으로 출력했습니다. 제어기에 따라 이송 속도가 경로를 따라 적용되지 않습니다. „극좌표 보간 켜기/끄기“ 템플릿을 입력하는 것이 좋습니다",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: 포스트 프로세서에 \"C축 및 구동 공구 켜기\" 템플릿이 없습니다 – C축과 공구 주축을 수동으로 켜세요",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: 포스트 프로세서에 원통 보간이 없습니다. Z와 C가 함께 이동하며, 제어기에 따라 이송 속도가 경로를 따라 적용되지 않습니다. „원통 보간 켜기/끄기“ 템플릿을 입력하는 것이 좋습니다",
"{0}: Postprozessor ohne {1} für diese Form – als Bahn ausgegeben":"{0}: 포스트 프로세서에 이 형상용 {1}이(가) 없습니다 – 경로로 출력됨",
"{0}: Schlichtzyklus folgt der Hüllkontur – Hinterschnitt/Einstich bleibt stehen":"{0}: 정삭 사이클은 외곽 윤곽을 따라갑니다. 언더컷/홈이 남습니다",
"{0}: Schlichtzyklus fährt die Fertigkontur – Aufmaß {1} mm wird nicht berücksichtigt":"{0}: 정삭 사이클은 완성 윤곽을 따라갑니다. 여유량 {1} mm는 반영되지 않습니다",
"{0}: Schlichtzyklus nicht möglich ({1}) – als Bahn ausgegeben":"{0}: 정삭 사이클을 사용할 수 없습니다({1}). 경로로 출력했습니다",
"{0}: Steuerung/Postprozessor ohne Gewindebohrzyklus – als Vorschubbewegung ausgegeben (nur mit Ausgleichsfutter!)":"{0}: 제어기/포스트 프로세서에 탭 사이클이 없습니다. 이송 동작으로 출력했습니다(플로팅 탭 홀더 사용 시에만!)",
"{0}: Steuerungszyklus nicht möglich (Tiefe 0) – als Bahn ausgegeben":"{0}: 컨트롤러 사이클을 사용할 수 없습니다(깊이 0) – 경로로 출력됨",
"{0}: Steuerungszyklus nicht möglich ({1}) – als Bahn ausgegeben":"{0}: 컨트롤러 사이클을 사용할 수 없습니다({1}) – 경로로 출력됨",
"{0}: Vorschub {1} > Maschinenmaximum {2} – begrenzt":"{0}: 이송 속도 {1} > 기계 최대값 {2} – 제한됨",
"{0}: Zyklus schruppt nur bis zur Hüllkontur – Hinterschnitt/Einstich bis {1} mm (Radius) bleibt stehen; vor dem Schlichten einstechen":"{0}: 사이클은 외곽 윤곽까지만 황삭합니다. {1} mm(반경)까지의 언더컷/홈이 남습니다. 정삭 전에 홈 가공을 하십시오",
"{0}: an diesen Punkten nicht möglich (Bogen, Spline, Linienende ohne zweite Linie oder bemaßte Rechteckmitte).":"{0}: 이 지점에서는 불가능합니다(호, 스플라인, 두 번째 선이 없는 선 끝점 또는 치수가 지정된 직사각형 중심).",
"{0}: bitte {1} wählen (Umschalt-Klick für mehrere).":"{0}: {1}을(를) 선택하세요(여러 개는 Shift+클릭).",
