"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"“+” = 공구가 새로 생성됩니다. 절삭 데이터는 초경 기준 권장값입니다({0}){1}. 냉각: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"“서로 맞물려 배치”는 블랭크를 이웃 블랭크의 틈과 오목한 부분, 그리고 그 컷아웃 안에 배치합니다(90° 회전 없이 180° 뒤집기만 사용). 간격은 항상 유지됩니다. 체크를 해제하면 외접 사각형 기준으로 줄지어 배치됩니다. “스케치 + 바디”를 선택하면 판 두께의 평평한 바디가 만들어지며, 제조에서 2D 윤곽으로 잘라낼 수 있습니다.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"'안쪽/바깥쪽'에는 닫힌 윤곽이 필요합니다. 열린 곡선은 '곡선 위'로 가공하십시오",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"“스케치 종료” → 돌출, 회전 또는 구멍.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"“스케치” → XY/XZ/YZ 평면을 선택하거나 평평한 면을 클릭하세요.",
"„{0}“ als Netz übernommen – {1} Dreiecke. Der Körper ist ausgeblendet.":"“{0}”을(를) 메시로 가져왔습니다 – 삼각형 {1}개. 바디는 숨겨졌습니다.",
"„{0}“ aus {1} löschen?":"{1}에서 “{0}”을(를) 삭제하시겠습니까?",
"„{0}“ eingefügt – {1} Dreiecke, bleibt als Netz (kein B-Rep)":"“{0}” 삽입됨 – 삼각형 {1}개, 메시로 유지됩니다(B-Rep 아님)",
"„{0}“ enthält keine Körper":"“{0}”에 바디가 없습니다",
"„{0}“ geschlossen – im Datenpanel weiterhin vorhanden":"“{0}”을(를) 닫았습니다 – 데이터 패널에는 계속 남아 있습니다",
"„{0}“ gespeichert – Version V{1}":"“{0}” 저장됨 – 버전 V{1}",
"„{0}“ geöffnet":"“{0}”을(를) 열었습니다",
"„{0}“ importiert – {1} Körper":"“{0}” 가져옴 – 바디 {1}개",
"„{0}“ ist fest belegt und kann nicht verwendet werden.":"„{0}“은(는) 고정으로 지정되어 있어 사용할 수 없습니다.",
"„{0}“ ist jetzt auch ein Körper (Verrundung, Ausschneiden, 2D-Bearbeitung möglich){1}{2}{3}. Das Netz ist ausgeblendet.":"“{0}”은(는) 이제 바디이기도 합니다 (모깎기, 잘라내기, 2D 가공 가능){1}{2}{3}. 메시는 숨겨져 있습니다.",
"„{0}“ ist kein gültiger Wert.":"„{0}“은(는) 유효한 값이 아닙니다.",
"„{0}“ liegt jetzt auf {1}.":"„{0}“이(가) 이제 {1}에 지정되었습니다.",
"„{0}“ löschen?":"“{0}”을(를) 삭제하시겠습니까?",
"„{0}“ mit T{1} vor dem Gewindefräsen angelegt":"나사 밀링 전에 T{1}로 „{0}“을(를) 만들었습니다",
"„{0}“ mit allen Versionen endgültig löschen?":"“{0}”을(를) 모든 버전과 함께 영구 삭제할까요?",
"„{0}“ nicht gefunden":"“{0}”을(를) 찾을 수 없습니다",
"„{0}“ steht jetzt in allen Projekten zur Verfügung":"“{0}”을(를) 이제 모든 프로젝트에서 사용할 수 있습니다",
