"⚠ Fehler":"⚠ 오류",
"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ 모든 NC 프로그램은 첫 실행 전에 검사하세요: 기계에서 시험 가동(싱글 블록, 급속 이송 감속)하거나 외부 NC 시뮬레이터로 확인합니다. 여기의 시뮬레이션은 이를 대체하지 않습니다 – 사용에 따른 책임은 사용자에게 있으며 보증하지 않습니다.",
"⚠ Kollision bei {0} von {1} Stellungen, z. B. {2}":"⚠ {1}개 위치 중 {0}개에서 충돌, 예: {2}",
"⚠ Kreisbögen mit R statt I/J werden nicht unterstützt – I/J wird ausgegeben":"⚠ I/J 대신 R을 사용하는 원호는 지원되지 않습니다 – I/J로 출력됩니다",
"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ 바디를 마지막으로 변경한 후 어느 모서리 또는 면을 가리키는지 분명하지 않게 되었습니다. 확인하고 필요하면 삭제한 뒤 다시 투영하세요.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ 프로그램 로직(JavaScript)은 실행되지 않습니다. 특수 기능, 4축/5축, 측정 사이클 및 기계 옵션은 포스트 프로세서 편집기에서 확인하세요.",
"⚠ {0} Abhängigkeit(en) nicht erfüllbar – Skizze überbestimmt oder widersprüchlich":"⚠ 구속조건 {0}개를 만족할 수 없습니다 – 스케치가 과구속이거나 모순됩니다",
"⚠ {0} Kollision{1}":"⚠ 충돌 {0}건{1}",
"⚠ {0} Operation(en) mit Fehler werden übersprungen.":"⚠ 오류가 있는 작업 {0}개는 건너뜁니다.",
"⚠ {0} – wird als Bahn ausgegeben.":"⚠ {0} – 공구 경로로 출력됩니다.",
"⚠ Überschneidungen:":"⚠ 간섭:",
"✎ Vorlage":"✎ 템플릿",
"✎ Vorlage „{0}“":"✎ 템플릿 “{0}”",
"✓ Auswahl beenden":"✓ 선택 종료",
"✓ Keine Kollision (Eilgänge, Futter, Fertigkontur, Schneidrichtung) – Zeile für Zeile gegen das jeweils verbliebene Rohteil geprüft":"✓ 충돌 없음(급속 이송, 척, 완성 윤곽, 절삭 방향) – 그 시점에 남아 있는 소재를 기준으로 한 줄씩 검사했습니다",
"✓ Keine Kollision im gesamten Bewegungsbereich":"✓ 전체 이동 범위에서 충돌 없음",
"✓ Keine Kollision mit dem Material (Halter, Schaft, Eilgänge){0} – Zeile für Zeile gegen das jeweils verbliebene Rohteil geprüft":"✓ 재료와 충돌 없음(홀더, 섕크, 급속 이송){0} – 그 시점에 남아 있는 소재를 기준으로 한 줄씩 검사했습니다",
"✓ Keine Überschneidungen zwischen den Körpern.":"✓ 바디 사이에 간섭이 없습니다.",
